B.aQ=new A.dY(B.c_,null)
B.ft=new A.xC("Nur gegart, roh giftig",1,"nurGegart")
B.f7=new A.dY(B.ft,null)
B.boS=new A.dY(B.c_,"Der Name meint mehrere Arten der Gattung Leccinum; sie gelten alle als Speisepilze und sind alle roh unvertr\xe4glich.")
B.brA=new A.dY(B.c_,"Die schleimige Huthaut wird meist abgezogen; sie kann abf\xfchrend wirken.")
B.bpp=new A.dY(B.ft,"Roh giftig. Gegart ein gesch\xe4tzter Speisepilz \u2014 die Blauf\xe4rbung beim Anschnitt ist kein Giftzeichen.")
B.bnx=new A.dY(B.ft,"Roh giftig, und auch gegart nicht von jedem vertragen.")
B.Fj=new A.xC("Ungenie\xdfbar",3,"ungeniessbar")
B.bpu=new A.dY(B.Fj,"Bitter, nicht giftig \u2014 ein einziger verdirbt aber ein ganzes Gericht. Wird mit dem Steinpilz verwechselt.")
B.lM=new A.dY(B.fs,null)
B.box=new A.dY(B.Fj,"Gallenbitter \u2014 ein einziger verdirbt das Gericht, und roh oder in Menge macht er Magen-Darm-Beschwerden. Wird f\xfcr Steinpilz oder Hexenr\xf6hrling gehalten.")
B.kA=new A.xC("Uneinheitlich beurteilt",2,"umstritten")
B.boN=new A.dY(B.kA,"Uneinheitlich beurteilt \u2014 nicht giftig im engeren Sinn, kann aber Magen-Darm-Beschwerden ausl\xf6sen.")
B.bpA=new A.dY(B.c_,"Junge Champignons werden mit jungen Knollenbl\xe4tterpilzen verwechselt \u2014 die haben wei\xdfe Lamellen und eine Scheide am Stielgrund.")
B.bpv=new A.dY(B.fs,"L\xe4uft an der Stielbasis chromgelb an und riecht beim Erhitzen nach Karbol. Die h\xe4ufigste Champignon-Vergiftung.")
B.brs=new A.dY(B.c_,"Nur ausgewachsene Exemplare mit genattertem Stiel und verschiebbarem Ring \u2014 H\xfcte unter zehn Zentimetern stehen lassen: Kleine Schirmlinge sind zum Teil t\xf6dlich giftig, und die sind in diesem Verzeichnis nicht einmal aufgef\xfchrt.")
B.bqd=new A.dY(B.kA,"Der Name meint mehrere Arten der Gattung Chlorophyllum. Roh giftig, und auch gegart werden sie nicht von jedem vertragen.")
B.boL=new A.dY(B.c_,"Nur solange die Lamellen wei\xdf sind \u2014 er zerflie\xdft innerhalb weniger Stunden zu schwarzer Tinte.")
B.bpl=new A.dY(B.ft,"Roh giftig. Wird mit dem giftigen Pantherpilz verwechselt \u2014 der eine r\xf6tet im Fleisch und an Fra\xdfstellen, der andere nicht.")
B.br3=new A.dY(B.fu,"Die mit Abstand h\xe4ufigste t\xf6dliche Pilzvergiftung in Mitteleuropa. Die Beschwerden beginnen erst Stunden sp\xe4ter, wenn die Leber bereits gesch\xe4digt ist.")
B.Ag=new A.dY(B.fu,null)
B.boV=new A.dY(B.ft,"Roh giftig. Ein Wulstling ohne Ring \u2014 die Verwechslung geht in Richtung der Knollenbl\xe4tterpilze.")
B.bpT=new A.dY(B.c_,"Gr\xfcnh\xfctige T\xe4ublinge werden mit dem Gr\xfcnen Knollenbl\xe4tterpilz verwechselt \u2014 T\xe4ublinge haben keine Scheide und keinen Ring.")
B.bn0=new A.dY(B.fs,"Brennend scharf; f\xfchrt roh zu Erbrechen.")
B.bqg=new A.dY(B.fs,"In Mitteleuropa ein Giftpilz (Magen-Darm). Dass er in Osteuropa nach langem Abkochen gegessen wird, ist kein Freibrief. Wird wegen der Stielgr\xfcbchen und verblasst fast gleicher Farbe f\xfcr einen Reizker gehalten \u2014 den Unterschied tr\xe4gt die Milch.")
B.bqG=new A.dY(B.ft,"Roh giftig \u2014 das gilt f\xfcr alle Morcheln.")
B.brr=new A.dY(B.fu,'Trotz des wissenschaftlichen Namens \u201eesculenta" (essbar): Das Gift Gyromitrin ist fl\xfcchtig, aber auch die D\xe4mpfe beim Kochen sind gef\xe4hrlich. Galt fr\xfcher als Speisepilz.')
B.bm5=new A.dY(B.kA,"Uneinheitlich beurteilt \u2014 roh giftig, und auch gegart sind Unvertr\xe4glichkeiten beschrieben.")
B.bsb=new A.dY(B.c_,"Nur solange das Fleisch rein wei\xdf ist. Gelb oder braun hei\xdft: reife Sporen, nicht mehr essbar.")
B.brM=new A.dY(B.c_,"Nur jung und innen rein wei\xdf. Halbiert man einen St\xe4ubling und sieht darin einen angelegten Pilz, ist es ein junger Knollenbl\xe4tterpilz.")
B.bmv=new A.dY(B.ft,"Nur die jungen, weichen R\xe4nder. An Eibe, Robinie und Eukalyptus gewachsen gilt er als unvertr\xe4glich.")
B.bpc=new A.dY(B.c_,"Jung mild, mit dem Alter zunehmend bitter.")
B.bq3=new A.dY(B.kA,"Der Name meint die ganze Gattung Ramaria. Einige Arten gelten als Speisepilze, andere wirken abf\xfchrend, und auseinanderhalten lassen sie sich im Feld kaum.")
B.bnG=new A.dY(B.c_,"In Deutschland besonders gesch\xfctzt \u2014 wild wachsende Exemplare d\xfcrfen nicht gesammelt werden. Im Handel stammt er aus Zucht.")
B.bmV=new A.dY(B.ft,"Wird mit dem t\xf6dlich giftigen Gifth\xe4ubling verwechselt, der am selben Holz w\xe4chst. Ohne sichere Bestimmung nicht sammeln.")
B.bsm=new A.dY(B.c_,"Zur selben Zeit am selben Ort wachsen der giftige Ziegelrote Risspilz und der Riesenr\xf6tling.")
B.bpj=new A.dY(B.ft,"Roh giftig, und auch gegart nicht von jedem vertragen. Das Kochwasser wird \xfcblicherweise weggegossen.")
B.blV=new A.dY(B.kA,"Uneinheitlich beurteilt \u2014 roh giftig, und Unvertr\xe4glichkeiten sind auch gegart beschrieben.")
B.brT=new A.dY(B.kA,"Galt lange als Speisepilz und steht heute zugleich auf der Giftpilzliste: h\xe4ufige Unvertr\xe4glichkeiten, dazu der Verdacht einer erbgutsch\xe4digenden Wirkung.")
B.bou=new A.dY(B.ft,"Roh giftig. W\xe4chst im Winter am selben Holz wie der t\xf6dlich giftige Gifth\xe4ubling.")
B.bnr=new A.dY(B.fu,"Dasselbe Gift wie im Gr\xfcnen Knollenbl\xe4tterpilz. Wird mit dem Stockschw\xe4mmchen verwechselt.")
B.bp1=new A.dY(B.fu,"Wurde jahrzehntelang als Speisepilz gesammelt. Das Gift wirkt nicht beim ersten Mal: Der K\xf6rper bildet Antik\xf6rper, und irgendwann zerst\xf6ren sie nach einer Mahlzeit die roten Blutk\xf6rperchen.")
B.bqU=new A.dY(B.fu,"Zerst\xf6rt die Nieren. Die ersten Beschwerden kommen erst nach Tagen bis Wochen \u2014 bis dahin denkt niemand mehr an den Pilz.")
